"""CDISC CORE in the environment: pins, drift, the runner's command, the report reader.

The functions that decide are tested on planted values (rule R5). CORE
itself is run by the gate gen-1a, not here: CI has no CORE.
"""

from __future__ import annotations

import json
import re

import pytest

from specfirst import cdisccore, doctor

LOCK = """\
# This file was autogenerated by uv via the following command:
#    bash env/lock.sh
pandas==3.1.1 \\
    --hash=sha256:aaa \\
    --hash=sha256:bbb
Setuptools_SCM==10.3.4 \\
    --hash=sha256:ccc
titlecase==2.4.1 \\
    --hash=sha256:ddd
"""


def test_the_pins_of_the_repository(root):
    pin = cdisccore.read_pin(root)
    assert pin.repository == "cdisc-org/cdisc-rules-engine"
    assert pin.tag == "v1.0.0" and pin.version == "1.0.0"
    assert re.fullmatch(r"[0-9a-f]{40}", pin.commit)
    assert pin.key == f"{pin.commit[:12]}-{pin.lock_sha256[:12]}"
    lock = cdisccore.read_lock((root / cdisccore.LOCK_FILE).read_text("ascii"))
    # The lock holds what CORE imports, and the one package that is built from source.
    for name in ("pandas", "business-rules-enhanced", "odmlib", "titlecase", "setuptools-scm"):
        assert name in lock, name
    assert "pyinstaller" not in lock and "cdisc-rules-engine" not in lock
    assert cdisccore.sdist_names(root) == {"titlecase"}
    # Every requirement of the lock has at least one hash: pip installs with --require-hashes.
    text = (root / cdisccore.LOCK_FILE).read_text("ascii")
    assert text.count("==") == len(lock) and text.count("--hash=sha256:") >= len(lock)


def test_a_changed_pin_gives_another_install_folder(root, tmp_path, monkeypatch):
    (tmp_path / "env").mkdir()
    for name in (cdisccore.SOURCE_FILE, cdisccore.LOCK_FILE):
        (tmp_path / name).write_bytes((root / name).read_bytes())
    monkeypatch.setenv("SPECFIRST_CORE", str(tmp_path / "home"))
    first = cdisccore.core_dir(tmp_path)
    assert first.parent == (tmp_path / "home").resolve()
    with open(tmp_path / cdisccore.LOCK_FILE, "a", encoding="ascii") as handle:
        handle.write("# changed\n")
    second = cdisccore.core_dir(tmp_path)
    assert second != first and second.name[:12] == first.name[:12]
    monkeypatch.delenv("SPECFIRST_CORE")
    assert cdisccore.core_dir(tmp_path).parent == tmp_path / ".core"
    (tmp_path / cdisccore.SOURCE_FILE).write_text("repository a/b\ntag v1\ncommit abc\n",
                                                  encoding="ascii")
    with pytest.raises(cdisccore.CoreError):
        cdisccore.read_pin(tmp_path)
    assert "CORE pins" in cdisccore.drift(tmp_path)[0]


def test_the_lock_is_split_into_wheels_and_source_builds():
    assert cdisccore.read_lock(LOCK) == {"pandas": "3.1.1", "setuptools-scm": "10.3.4",
                                         "titlecase": "2.4.1"}
    wheels, sources = cdisccore.split_lock(LOCK, {"titlecase"})
    assert "pandas==3.1.1" in wheels and "--hash=sha256:bbb" in wheels
    assert "titlecase" not in wheels and "#" not in wheels
    assert sources == "titlecase==2.4.1 \\\n    --hash=sha256:ddd\n"
    assert cdisccore.split_lock(LOCK, set())[1] == ""


def test_package_drift_reports_planted_differences():
    lock = {"pandas": "3.1.1", "titlecase": "2.4.1"}
    assert cdisccore.package_drift(lock, {**lock, "pip": "24.0"}) == []
    assert cdisccore.package_drift(lock, {"pandas": "3.0.0", "titlecase": "2.4.1"}) == [
        "CORE environment: pandas is 3.0.0, lock has 3.1.1"]
    assert cdisccore.package_drift(lock, {"pandas": "3.1.1"}) == [
        "CORE environment: titlecase is not installed, lock has 2.4.1"]
    assert cdisccore.package_drift(lock, {**lock, "requests": "2.34.2"}) == [
        "CORE environment: requests 2.34.2 is not in the lock"]
    assert cdisccore.normalize("Setuptools_SCM") == "setuptools-scm"


def test_the_source_must_be_the_pinned_commit_untouched(repo, git):
    commit = git(repo, "rev-parse", "HEAD")
    assert cdisccore.source_problems(repo, commit) == []
    assert "HEAD is" in cdisccore.source_problems(repo, "0" * 40)[0]
    (repo / "left-behind.pyc").write_bytes(b"x")
    assert "not clean" in cdisccore.source_problems(repo, commit)[0]
    assert "not installed" in cdisccore.source_problems(repo / "nowhere", commit)[0]


def test_doctor_fails_when_core_is_not_installed(root, tmp_path, monkeypatch):
    monkeypatch.setenv("SPECFIRST_CORE", str(tmp_path / "empty"))
    problems = cdisccore.drift(root)
    assert len(problems) == 1 and "not installed" in problems[0]
    assert doctor._two_words(root / cdisccore.SOURCE_FILE)["tag"] == "v1.0.0"


def test_the_runner_limits_the_worker_pool_of_core(tmp_path):
    """Lesson 27: without a pool size CORE starts one worker per processor."""
    argv = cdisccore.command_line(
        tmp_path / "python", tmp_path / "src", [tmp_path / "dm.json", tmp_path / "ae.json"],
        tmp_path / "report", tmp_path / "define.xml", "sdtmig", "3-4")
    assert argv[:4] == [str(tmp_path / "python"), "-B", str(tmp_path / "src" / "core.py"),
                        "validate"]
    assert argv[argv.index("-ps") + 1] == str(cdisccore.POOL_SIZE) and cdisccore.POOL_SIZE <= 2
    assert argv.count("-dp") == 2 and argv[argv.index("-dxp") + 1].endswith("define.xml")
    assert argv[argv.index("-of") + 1] == "JSON"
    without = cdisccore.command_line(tmp_path / "python", tmp_path / "src", [], tmp_path / "r",
                                     None, "sdtmig", "3-4", terminology=("sdtmct-2025-09-26",))
    assert "-dxp" not in without and without[-2:] == ["-ct", "sdtmct-2025-09-26"]


REPORT = {
    "Conformance_Details": {"CORE_Engine_Version": "1.0.0", "Standard": "SDTMIG",
                            "Version": "V3.4", "Report_Generation": "2026-11-17T10:42:43",
                            "CT_Version": "sdtmct-2025-09-26", "Define_XML_Version": "2.1.0"},
    "Dataset_Details": [{"filename": "DM", "length": 149}, {"filename": "AE", "length": 145}],
    "Issue_Summary": [
        {"dataset": "DM", "core_id": "CORE-000655", "message": "arms differ", "issues": 2},
        {"dataset": "AE", "core_id": "CORE-002034", "message": "no flag", "issues": 3},
        {"dataset": "AE", "core_id": "CORE-002008", "message": "rule execution error",
         "issues": 1},
    ],
    "Issue_Details": [
        {"core_id": "CORE-000655", "message": "arms differ", "dataset": "DM", "USUBJID": "S-2",
         "row": 2, "variables": ["ARMCD", "ACTARMCD"], "values": ["A", "B"]},
        {"core_id": "CORE-000655", "message": "arms differ", "dataset": "DM", "USUBJID": "S-1",
         "row": 1, "variables": ["ARMCD", "ACTARMCD"], "values": ["A", "B"]},
        {"core_id": "CORE-002008", "message": "rule execution error", "dataset": "AE",
         "USUBJID": "", "row": "", "variables": "", "values": "Rule contains invalid operator"},
    ],
    "Rules_Report": [
        {"core_id": "CORE-000001", "status": "SUCCESS", "message": "fine"},
        {"core_id": "CORE-000002", "status": "SKIPPED", "message": "not here"},
        {"core_id": "CORE-000655", "status": "ISSUE REPORTED", "message": "arms differ"},
        {"core_id": "CORE-002034", "status": "ISSUE REPORTED", "message": "no flag"},
        {"core_id": "CORE-002008", "status": "EXECUTION ERROR", "message": "broken"},
        {"core_id": "CORE-002999", "status": "EXECUTION ERROR", "message": "broken, no detail"},
    ],
}


def test_a_report_is_read_as_findings(tmp_path):
    path = tmp_path / "report.json"
    path.write_text(json.dumps(REPORT), encoding="utf-8")
    report = cdisccore.read_report(path)
    assert (report.engine, report.standard) == ("1.0.0", "SDTMIG V3.4")
    assert report.counts() == {"EXECUTION ERROR": 2, "ISSUE REPORTED": 2, "SKIPPED": 1,
                               "SUCCESS": 1}
    found = {(f.rule, f.dataset): f for f in report.findings}
    assert set(found) == {("CORE-000655", "DM"), ("CORE-002034", "AE"), ("CORE-002008", "AE"),
                          ("CORE-002999", "")}
    arms = found["CORE-000655", "DM"]
    assert (arms.status, arms.count, arms.subjects) == ("ISSUE REPORTED", 2, ("S-1", "S-2"))
    assert arms.variables == ("ACTARMCD", "ARMCD")
    assert (arms.listed, arms.named) == (2, 2)
    # A summary line without details keeps its count; it names no subject.
    flag = found["CORE-002034", "AE"]
    assert (flag.count, flag.subjects, flag.listed, flag.named) == (3, (), 0, 0)
    assert found["CORE-002008", "AE"].status == "EXECUTION ERROR"
    assert (found["CORE-002008", "AE"].listed, found["CORE-002008", "AE"].named) == (1, 0)
    # A rule that could not run and has no line of its own is a finding all the same.
    assert found["CORE-002999", ""].status == "EXECUTION ERROR"
    assert report.datasets == ("DM", "AE")
    # What ties a report to a run: the records CORE read, the Define-XML, the terminology.
    assert report.records == {"DM": 149, "AE": 145}
    assert (report.define, report.terminology) == ("2.1.0", "sdtmct-2025-09-26")
    bare = dict(REPORT, Conformance_Details={}, Dataset_Details=[{"filename": "DM"}])
    path.write_text(json.dumps(bare), encoding="utf-8")
    report = cdisccore.read_report(path)
    assert (report.records, report.define, report.terminology) == ({"DM": 0}, "", "")


def test_the_requirements_are_those_of_the_pinned_core(root, tmp_path):
    """Review finding F14: nothing compared env/core-requirements.in with CORE's own list."""
    lines = [line.split("#", 1)[0].strip()
             for line in (root / cdisccore.IN_FILE).read_text("ascii").splitlines()]
    ours = [line for line in lines if line]
    assert len(ours) == 26 and "setuptools_scm>=8" in ours

    def source(dependencies):
        quoted = ",\n".join(f'    "{line}"' for line in dependencies)
        (tmp_path / "pyproject.toml").write_text(
            f"[project]\nname = \"cdisc-rules-engine\"\ndependencies = [\n{quoted},\n]\n",
            encoding="ascii")
        return cdisccore.requirement_problems(root, tmp_path)

    # CORE writes its list with spaces and names pyinstaller; ours adds setuptools_scm.
    theirs = [line.replace(">=", " >=", 1) for line in ours if line != "setuptools_scm>=8"]
    theirs.append("pyinstaller >=6.11.0")
    assert source(theirs) == []
    # Planted defects: a bound CORE raised, a dependency it added, one it dropped.
    raised = [line.replace("pandas >=3.0.0", "pandas >=3.1.0") for line in theirs]
    assert source(raised) == [
        "env/core-requirements.in: pandas is '>=3.0.0' here and '>=3.1.0' in pyproject.toml "
        "of the pinned CORE"]
    assert source([*theirs, "polars >=1.0"]) == [
        "env/core-requirements.in: polars is 'absent' here and '>=1.0' in pyproject.toml of "
        "the pinned CORE"]
    assert source([line for line in theirs if not line.startswith("redis")]) == [
        "env/core-requirements.in: redis is '>=4.5.0' here and 'absent' in pyproject.toml of "
        "the pinned CORE"]
    assert source([line.replace("dask[dataframe,array]", "dask[dataframe]")
                   for line in theirs])[0].startswith("env/core-requirements.in: dask[dataframe")
    (tmp_path / "pyproject.toml").write_text("[project]\nname = 'x'\n", encoding="ascii")
    assert "cannot read the dependencies" in cdisccore.requirement_problems(root, tmp_path)[0]
    (tmp_path / "pyproject.toml").unlink()
    assert "cannot read the dependencies" in cdisccore.requirement_problems(root, tmp_path)[0]


def test_validate_refuses_to_run_without_an_install(root, tmp_path, monkeypatch):
    monkeypatch.setenv("SPECFIRST_CORE", str(tmp_path / "empty"))
    with pytest.raises(cdisccore.CoreError, match="not installed"):
        cdisccore.validate(root, [], tmp_path / "report")
    with pytest.raises(cdisccore.CoreError, match="no package sdtmct-2025-09-26"):
        cdisccore.terminology(root, "sdtmct-2025-09-26")
    assert cdisccore.main(["nonsense"]) == 2
